SELECT "REGION" AS "REGION", "SEVERITY" AS "SEVERITY", COUNT(*) AS count, count(DISTINCT "NODE") AS "COUNT_DISTINCT(NODE)" 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' GROUP BY "REGION", "SEVERITY" 
 LIMIT 10000;